   888      char *crlfcrlf = memmem(helper->buffer->value, helper->buffer->len, "\r\n\r\n", 4);
   889      if (LIKELY(crlfcrlf)) {
   890          helper->crlfcrlf = crlfcrlf;
   891          return FINALIZER_DONE;
   892      }
   893
   894      if (LIKELY(helper->next_request)) {
   895          helper->next_request = NULL;
   896          return FINALIZER_DONE;
   897      }
   898
   899      return FINALIZER_TRY_AGAIN;
   900  }
