   933  static ALWAYS_INLINE int max(int a, int b)
   934  {
   935      return (a > b) ? a : b;
   936  }
   937
   938  static ALWAYS_INLINE int calculate_n_packets(size_t total)
   939  {
   940      /* 740 = 1480 (a common MTU) / 2, so that Lwan'll optimistically error out
   941       * after ~2x number of expected packets to fully read the request body.*/
   942      return max(1, (int)(total / 740));
   943  }
