   945  static const char *is_dir(const char *v)
   946  {
   947      struct stat st;
   948
   949      if (!v)
   950          return NULL;
   951
   952      if (*v != '/')
   953          return NULL;
   954
   955      if (stat(v, &st) < 0)
   956          return NULL;
   957
   958      if (!S_ISDIR(st.st_mode))
   959          return NULL;
   960
   960
   961      if (!(st.st_mode & S_ISVTX)) {
   962          lwan_status_warning(
   963              "Using %s as temporary directory, but it doesn't have "
   964              "the sticky bit set.",
   965              v);
   966      }
   967
   968      return v;
   969  }
