  1006  static int create_temp_file(void)
  1007  {
  1008      char template[PATH_MAX];
  1009      mode_t prev_mask;
  1010      int ret;
  1011
  1012      if (UNLIKELY(!temp_dir))
  1013          return -ENOENT;
  1014
  1015  #if defined(O_TMPFILE)
  1016      int fd = open(temp_dir,
  1017                    O_TMPFILE | O_CREAT | O_RDWR | O_EXCL | O_CLOEXEC |
  1018                        O_NOFOLLOW | O_NOATIME,
  1019                    S_IRUSR | S_IWUSR);
  1020      if (LIKELY(fd >= 0))
  1021          return fd;
  1022  #endif
  1023
  1024      ret = snprintf(template, sizeof(template), "%s/lwanXXXXXX", temp_dir);
  1025      if (UNLIKELY(ret < 0 || ret >= (int)sizeof(template)))
  1026          return -EOVERFLOW;
  1027
  1028      prev_mask = umask_for_tmpfile(S_IRUSR | S_IWUSR);
  1029      ret = mkostemp(template, O_CLOEXEC);
  1030      umask_for_tmpfile(prev_mask);
  1031
  1032      if (LIKELY(ret >= 0))
  1033          unlink(template);
  1034
  1035      return ret;
  1036  }
