  1052  static void*
  1053  alloc_post_buffer(struct coro *coro, size_t size, bool allow_file)
  1054  {
  1055      struct file_backed_buffer *buf;
  1056      void *ptr = (void *)MAP_FAILED;
  1057      int fd;
  1058
  1059      if (LIKELY(size < 1<<20)) {
  1060          ptr = coro_malloc(coro, size);
  1061
  1062          if (LIKELY(ptr))
  1063              return ptr;
  1064      }
  1065
  1066      if (UNLIKELY(!allow_file))
  1067          return NULL;
  1068
  1069      fd = create_temp_file();
  1070      if (UNLIKELY(fd < 0))
  1071          return NULL;
  1072
  1073      if (UNLIKELY(ftruncate(fd, (off_t)size) < 0)) {
  1074          close(fd);
  1075          return NULL;
  1076      }
  1077
  1078      if (MAP_HUGETLB) {
  1079          ptr = mmap(NULL, size, PROT_READ | PROT_WRITE,
  1080                     MAP_PRIVATE | MAP_HUGETLB, fd, 0);
